package dao;
import database.DatabaseConnection; import model.Appointment; import java.sql.*; import java.util.*;
public class AppoinmentDAO {
 public boolean add(String residentId,int serviceId,String purpose,String date,String time){
  String check="SELECT COUNT(*) FROM appointments WHERE appointment_date=? AND appointment_time=? AND status NOT IN ('Cancelled')";
  try(Connection c=DatabaseConnection.getConnection();PreparedStatement cp=c.prepareStatement(check)){cp.setDate(1,java.sql.Date.valueOf(date));cp.setString(2,time);try(ResultSet r=cp.executeQuery()){r.next();if(r.getInt(1)>0)return false;}}catch(SQLException e){e.printStackTrace();return false;}
  String sql="INSERT INTO appointments(resident_id,service_id,purpose,appointment_date,appointment_time,status) VALUES(?,?,?,?,?,'Pending')";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,residentId);p.setInt(2,serviceId);p.setString(3,purpose);p.setDate(4,java.sql.Date.valueOf(date));p.setString(5,time);return p.executeUpdate()>0;}catch(SQLException e){e.printStackTrace();return false;}}
 public List<Appointment> getAll(){return query("SELECT a.*,CONCAT(r.first_name,' ',r.last_name) resident_name,s.service_name FROM appointments a JOIN residents r ON r.id_number=a.resident_id JOIN services s ON s.id=a.service_id ORDER BY a.appointment_date,a.appointment_time",null);}
 public List<Appointment> getByResident(String id){return query("SELECT a.*,CONCAT(r.first_name,' ',r.last_name) resident_name,s.service_name FROM appointments a JOIN residents r ON r.id_number=a.resident_id JOIN services s ON s.id=a.service_id WHERE a.resident_id=? ORDER BY a.appointment_date,a.appointment_time",id);}
 public boolean setStatus(int id,String status){try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE appointments SET status=? WHERE id=?")){p.setString(1,status);p.setInt(2,id);return p.executeUpdate()>0;}catch(SQLException e){e.printStackTrace();return false;}}
 private List<Appointment> query(String sql,String arg){List<Appointment> l=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(sql)){if(arg!=null)p.setString(1,arg);try(ResultSet r=p.executeQuery()){while(r.next())l.add(new Appointment(r.getInt("id"),r.getString("resident_id"),r.getString("resident_name"),r.getString("service_name"),r.getString("purpose"),r.getString("appointment_date"),r.getString("appointment_time"),r.getString("status")));}}catch(SQLException e){e.printStackTrace();}return l;}
}
